"""Ids are UUIDv7: generated by the database and ordered by creation time."""

import uuid

from sqlalchemy import text
from sqlalchemy.orm import Session

from app.auth.models import AuthUser


def test_database_generates_version_7_ids(db: Session) -> None:
    generated = db.execute(text("SELECT uuidv7()")).scalar_one()

    assert isinstance(generated, uuid.UUID)
    assert generated.version == 7
    assert generated.variant == uuid.RFC_4122


def test_ids_follow_creation_time(db: Session) -> None:
    # Each id carries its millisecond; pg_sleep makes sure they fall in different ones.
    ids = [db.execute(text("SELECT uuidv7() FROM pg_sleep(0.002)")).scalar_one() for _ in range(5)]

    assert ids == sorted(ids)


def test_tables_use_uuidv7_by_default(db: Session) -> None:
    user = AuthUser(email="ana@example.com")
    db.add(user)
    db.flush()

    assert user.id.version == 7
